# Hypothesis: output is periodic with period 4 along columns AND period...? check col period of each row pattern. Actually demo1&2 outputs have col period 4 within blocks but noise broke it. 
# New idea: maybe output = mode over a 3x3 neighborhood, iterated to fixpoint; we saw that failed on one pass. Try iterative majority (each cell becomes neighborhood mode), repeated until stable.
def f(g,k,tie):
    H,W=len(g),len(g[0]); res=[[g[i][j] for j in range(W)] for i in range(H)]
    def nb(i,j):
        out=[]
        for di in range(-k,k+1):
            for dj in range(-k,k+1):
                ii,jj=i+di,j+dj
                if 0<=ii<H and 0<=jj<W and (di,dj)!=(0,0): out.append(g[ii][jj])
        return out
    changed=True
    while changed:
        changed=False
        for i in range(H):
            for j in range(W):
                cnt=collections.Counter(nb(i,j))
                mx=max(cnt.values())
                top=[v for v,c in cnt.items() if c==mx]
                if len(top)>1 and tie==True: top=top
                v=res[i][j]
                if v not in cnt: continue
                # flip to mode
                newc=cnt.most_common(1)[0][0]
                if newc!=v:
                    res[i][j]=newc; changed=True
    return res
